# Generated by the offline AFL-UAV reproduction fixture.
import argparse
import heapq
import json
import math
import random


def read_problem(path: str) -> dict:
    with open(path, "r", encoding="utf-8") as stream:
        problem = json.load(stream)
    required = {
        "schema_version", "environment", "objective_weights",
        "grid_resolution", "max_waypoints"
    }
    missing = sorted(required.difference(problem))
    if missing:
        raise ValueError("missing problem fields: " + ", ".join(missing))
    if problem["schema_version"] != "afl-uav-instance-v1":
        raise ValueError("unsupported schema_version")
    environment = problem["environment"]
    environment_required = {
        "width", "height", "start", "goal", "obstacles",
        "risk_zones", "safety_distance", "seed"
    }
    missing_environment = sorted(environment_required.difference(environment))
    if missing_environment:
        raise ValueError(
            "missing environment fields: " + ", ".join(missing_environment)
        )
    return problem


def _distance(a, b):
    return math.hypot(float(a[0]) - float(b[0]), float(a[1]) - float(b[1]))


def _point_segment_distance(point, start, end):
    dx = float(end[0]) - float(start[0])
    dy = float(end[1]) - float(start[1])
    denominator = dx * dx + dy * dy
    if denominator <= 1e-18:
        return _distance(point, start)
    projection = (
        (float(point[0]) - float(start[0])) * dx
        + (float(point[1]) - float(start[1])) * dy
    ) / denominator
    projection = max(0.0, min(1.0, projection))
    closest = [float(start[0]) + projection * dx, float(start[1]) + projection * dy]
    return _distance(point, closest)


def _segment_intersects_box(start, end, min_x, min_y, max_x, max_y):
    x0, y0 = float(start[0]), float(start[1])
    dx = float(end[0]) - x0
    dy = float(end[1]) - y0
    lower, upper = 0.0, 1.0
    for coefficient, offset in (
        (-dx, x0 - min_x),
        (dx, max_x - x0),
        (-dy, y0 - min_y),
        (dy, max_y - y0),
    ):
        if abs(coefficient) <= 1e-15:
            if offset < 0.0:
                return False
            continue
        ratio = offset / coefficient
        if coefficient < 0.0:
            if ratio > upper:
                return False
            lower = max(lower, ratio)
        else:
            if ratio < lower:
                return False
            upper = min(upper, ratio)
    return lower <= upper


def segment_collision_free(start, end, problem) -> bool:
    metrics = problem.setdefault(
        "_metrics",
        {"objective_evaluations": 0, "collision_checks": 0, "node_expansions": 0},
    )
    metrics["collision_checks"] += 1
    environment = problem["environment"]
    width = float(environment["width"])
    height = float(environment["height"])
    for point in (start, end):
        x, y = float(point[0]), float(point[1])
        if not (math.isfinite(x) and math.isfinite(y)):
            return False
        if x < 0.0 or x > width or y < 0.0 or y > height:
            return False
    safety = float(environment["safety_distance"])
    for obstacle in environment["obstacles"]:
        if obstacle["kind"] == "circle":
            clearance = _point_segment_distance(obstacle["center"], start, end)
            if clearance <= float(obstacle["radius"]) + safety + 1e-9:
                return False
        elif obstacle["kind"] == "rectangle":
            if _segment_intersects_box(
                start,
                end,
                float(obstacle["min_x"]) - safety,
                float(obstacle["min_y"]) - safety,
                float(obstacle["max_x"]) + safety,
                float(obstacle["max_y"]) + safety,
            ):
                return False
        else:
            raise ValueError("unknown obstacle kind")
    return True


def _point_in_risk_zone(point, zone):
    return (
        float(zone["min_x"]) <= float(point[0]) <= float(zone["max_x"])
        and float(zone["min_y"]) <= float(point[1]) <= float(zone["max_y"])
    )


def path_cost(path, problem) -> float:
    metrics = problem.setdefault(
        "_metrics",
        {"objective_evaluations": 0, "collision_checks": 0, "node_expansions": 0},
    )
    metrics["objective_evaluations"] += 1
    weights = problem["objective_weights"]
    environment = problem["environment"]
    length = sum(_distance(start, end) for start, end in zip(path, path[1:]))
    collision = sum(
        0.0 if segment_collision_free(start, end, problem) else 1.0
        for start, end in zip(path, path[1:])
    )
    smoothness = 0.0
    for first, middle, last in zip(path, path[1:], path[2:]):
        left = [float(first[0]) - float(middle[0]), float(first[1]) - float(middle[1])]
        right = [float(last[0]) - float(middle[0]), float(last[1]) - float(middle[1])]
        denominator = math.hypot(*left) * math.hypot(*right)
        if denominator > 1e-12:
            cosine = max(-1.0, min(1.0, (left[0] * right[0] + left[1] * right[1]) / denominator))
            angle = math.acos(cosine)
            smoothness += (angle / math.pi) ** 2
    risk = 0.0
    sample_count = 16
    for start, end in zip(path, path[1:]):
        segment_length = _distance(start, end)
        for zone in environment["risk_zones"]:
            inside = 0
            for index in range(sample_count):
                fraction = (index + 0.5) / sample_count
                point = [
                    float(start[0]) + fraction * (float(end[0]) - float(start[0])),
                    float(start[1]) + fraction * (float(end[1]) - float(start[1])),
                ]
                inside += int(_point_in_risk_zone(point, zone))
            risk += segment_length * inside / sample_count * float(zone["weight"])
    waypoint = float(max(0, len(path) - 2))
    return (
        float(weights["length"]) * length
        + float(weights["collision"]) * collision
        + float(weights["smoothness"]) * smoothness
        + float(weights["risk"]) * risk
        + float(weights["waypoint"]) * waypoint
    )


def initial_path(problem):
    environment = problem["environment"]
    start = [float(value) for value in environment["start"]]
    goal = [float(value) for value in environment["goal"]]
    if segment_collision_free(start, goal, problem):
        return [start, goal]
    resolution = float(problem["grid_resolution"])
    width = float(environment["width"])
    height = float(environment["height"])
    x_count = int(math.ceil(width / resolution))
    y_count = int(math.ceil(height / resolution))
    points = [start, goal]
    grid = {}
    reverse_grid = {}
    for ix in range(x_count + 1):
        x = min(width, ix * resolution)
        for iy in range(y_count + 1):
            y = min(height, iy * resolution)
            point = [x, y]
            if _distance(point, start) <= 1e-9 or _distance(point, goal) <= 1e-9:
                continue
            if not segment_collision_free(point, point, problem):
                continue
            node = len(points)
            points.append(point)
            grid[(ix, iy)] = node
            reverse_grid[node] = (ix, iy)
    if not grid:
        raise RuntimeError("no collision-free grid nodes")

    def visible_links(point):
        candidates = sorted(grid.values(), key=lambda node: _distance(point, points[node]))
        links = []
        for node in candidates:
            if segment_collision_free(point, points[node], problem):
                links.append(node)
            if len(links) >= 24:
                break
        return links

    start_links = visible_links(start)
    goal_links = visible_links(goal)
    if not start_links or not goal_links:
        raise RuntimeError("start or goal cannot connect to the planning grid")
    start_link_set = set(start_links)
    goal_link_set = set(goal_links)

    def neighbors(node):
        if node == 0:
            return start_links
        if node == 1:
            return goal_links
        ix, iy = reverse_grid[node]
        output = []
        for dx in (-1, 0, 1):
            for dy in (-1, 0, 1):
                if dx == 0 and dy == 0:
                    continue
                candidate = grid.get((ix + dx, iy + dy))
                if candidate is not None and segment_collision_free(
                    points[node], points[candidate], problem
                ):
                    output.append(candidate)
        if node in start_link_set:
            output.append(0)
        if node in goal_link_set:
            output.append(1)
        return output

    frontier = [(0.0, 0.0, 0)]
    parent = {0: None}
    best = {0: 0.0}
    while frontier:
        _, current_cost, node = heapq.heappop(frontier)
        if current_cost > best.get(node, float("inf")) + 1e-12:
            continue
        problem["_metrics"]["node_expansions"] += 1
        if node == 1:
            break
        for candidate in neighbors(node):
            new_cost = current_cost + _distance(points[node], points[candidate])
            if new_cost + 1e-12 >= best.get(candidate, float("inf")):
                continue
            best[candidate] = new_cost
            parent[candidate] = node
            priority = new_cost + _distance(points[candidate], goal)
            heapq.heappush(frontier, (priority, new_cost, candidate))
    if 1 not in parent:
        raise RuntimeError("no feasible path found by grid search")
    nodes = []
    node = 1
    while node is not None:
        nodes.append(node)
        node = parent[node]
    path = [points[node] for node in reversed(nodes)]
    simplified = [path[0]]
    anchor = 0
    while anchor < len(path) - 1:
        candidate = len(path) - 1
        while candidate > anchor + 1:
            if segment_collision_free(path[anchor], path[candidate], problem):
                break
            candidate -= 1
        simplified.append(path[candidate])
        anchor = candidate
    return simplified


def destroy(path, rng):
    candidate = [list(point) for point in path]
    if len(candidate) <= 2:
        return candidate
    left = rng.randrange(0, len(candidate) - 2)
    right = rng.randrange(left + 2, len(candidate))
    return candidate[: left + 1] + candidate[right:]


def repair(original, candidate, problem, rng):
    del rng
    if validate_path(candidate, problem):
        return [list(point) for point in candidate]
    return [list(point) for point in original]


def validate_path(path, problem) -> bool:
    environment = problem["environment"]
    if not isinstance(path, list) or len(path) < 2:
        return False
    if len(path) > int(problem["max_waypoints"]):
        return False
    canonical = []
    for point in path:
        if not isinstance(point, (list, tuple)) or len(point) != 2:
            return False
        x, y = float(point[0]), float(point[1])
        if not (math.isfinite(x) and math.isfinite(y)):
            return False
        canonical.append([x, y])
    if _distance(canonical[0], environment["start"]) > 1e-7:
        return False
    if _distance(canonical[-1], environment["goal"]) > 1e-7:
        return False
    return all(
        segment_collision_free(start, end, problem)
        for start, end in zip(canonical, canonical[1:])
    )


def main() -> None:
    parser = argparse.ArgumentParser(description="Self-contained AFL-UAV solver")
    parser.add_argument("--path", required=True)
    parser.add_argument("--iteration", type=int, default=100)
    parser.add_argument("--max-evaluations", type=int, default=2000)
    parser.add_argument("--seed", type=int)
    parser.add_argument("--output", required=True)
    arguments = parser.parse_args()
    problem = read_problem(arguments.path)
    problem["_metrics"] = {
        "objective_evaluations": 0,
        "collision_checks": 0,
        "node_expansions": 0,
    }
    seed = (
        int(problem["environment"]["seed"])
        if arguments.seed is None
        else int(arguments.seed)
    )
    rng = random.Random(seed)
    current = initial_path(problem)
    if not validate_path(current, problem):
        raise RuntimeError("initial path is infeasible")
    initial_cost = path_cost(current, problem)
    current_cost = initial_cost
    best = [list(point) for point in current]
    best_cost = current_cost
    iteration_count = max(0, int(arguments.iteration))
    max_evaluations = max(1, int(arguments.max_evaluations))
    completed_iterations = 0
    start_temperature = max(1e-9, 0.05 * max(1.0, current_cost))
    end_temperature = max(1e-9, 0.001 * max(1.0, current_cost))
    for step in range(iteration_count):
        if problem["_metrics"]["objective_evaluations"] >= max_evaluations:
            break
        completed_iterations += 1
        destroyed = destroy(current, rng)
        candidate = repair(current, destroyed, problem, rng)
        if not validate_path(candidate, problem):
            continue
        candidate_cost = path_cost(candidate, problem)
        progress = step / max(1, iteration_count - 1)
        temperature = start_temperature * (
            end_temperature / start_temperature
        ) ** progress
        delta = candidate_cost - current_cost
        if delta <= 0.0 or rng.random() < math.exp(-delta / max(temperature, 1e-12)):
            current = candidate
            current_cost = candidate_cost
        if current_cost < best_cost:
            best = [list(point) for point in current]
            best_cost = current_cost
    result = {
        "status": "success",
        "initial_cost": initial_cost,
        "best_cost": best_cost,
        "path": best,
        "iterations": completed_iterations,
        "requested_iterations": iteration_count,
        "seed": seed,
        "objective_evaluations": problem["_metrics"]["objective_evaluations"],
        "collision_checks": problem["_metrics"]["collision_checks"],
        "node_expansions": problem["_metrics"]["node_expansions"],
    }
    with open(arguments.output, "w", encoding="utf-8") as stream:
        json.dump(result, stream, ensure_ascii=False, sort_keys=True, allow_nan=False)
    print(json.dumps(result, ensure_ascii=False, sort_keys=True, allow_nan=False))


if __name__ == "__main__":
    main()
